import java.io.IOException;

public class Shape {
    static void risky() throws IOException { throw new IOException("boom"); }

    public static void main(String[] args) {
        try {
            risky();
        } catch (IOException e) {
            System.out.println("handled: " + e.getMessage());
        } finally {
            System.out.println("always runs");
        }
    }
}

public class MultiCatch {
    public static void main(String[] args) {
        String[] inputs = {"42", "abc", null};
        for (String s : inputs) {
            try {
                int n = Integer.parseInt(s.trim());
                System.out.println("parsed " + n);
            } catch (NumberFormatException | NullPointerException e) {
                System.out.println("bad input '" + s + "': " + e.getClass().getSimpleName());
            }
        }
    }
}

public class FinallyOrder {
    static int f() {
        try {
            System.out.println("try");
            return 1;
        } finally {
            System.out.println("finally");
        }
    }

    @SuppressWarnings("finally")
    static int g() {
        try {
            throw new IllegalStateException("lost");
        } finally {
            return 2;   // swallows the exception
        }
    }

    static int h() {
        int x = 10;
        try {
            return x;
        } finally {
            x = 99;     // does not change the value already chosen to return
        }
    }

    public static void main(String[] args) {
        System.out.println(f());
        System.out.println(g());
        System.out.println(h());
    }
}

public class Suppressed {
    static class Res implements AutoCloseable {
        private final String name;
        Res(String name) { this.name = name; System.out.println("open " + name); }
        void work() { throw new IllegalStateException("work failed on " + name); }
        @Override public void close() {
            System.out.println("close " + name);
            throw new IllegalArgumentException("close failed on " + name);
        }
    }

    public static void main(String[] args) {
        try (Res a = new Res("A"); Res b = new Res("B")) {
            b.work();
        } catch (Exception e) {
            System.out.println("caught: " + e);
            for (Throwable s : e.getSuppressed()) {
                System.out.println("  suppressed: " + s);
            }
        }
    }
}

public class Chain {
    static class AccountException extends Exception {
        private final String accountId;
        AccountException(String message, String accountId, Throwable cause) {
            super(message, cause);
            this.accountId = accountId;
        }
        String accountId() { return accountId; }
    }

    static void low() throws java.io.IOException {
        throw new java.io.IOException("disk full");
    }

    static void mid() throws AccountException {
        try {
            low();
        } catch (java.io.IOException e) {
            throw new AccountException("cannot save account", "ACC-7", e);
        }
    }

    public static void main(String[] args) {
        try {
            mid();
        } catch (AccountException e) {
            System.out.println(e.getMessage() + " for " + e.accountId());
            System.out.println("cause: " + e.getCause());
            e.printStackTrace(System.out);
        }
    }
}

import java.lang.System.Logger;
import java.lang.System.Logger.Level;

public class LogPattern {
    private static final Logger LOG = System.getLogger("LogPattern");

    public static void main(String[] args) {
        try {
            Integer.parseInt("12x");
        } catch (NumberFormatException e) {
            LOG.log(Level.ERROR, "could not read quantity", e);   // good: message + exception
            // LOG.log(Level.ERROR, e.getMessage());               // bad: loses the stack trace
        }
    }
}

import java.io.IOException;

public class Rethrow {
    static void read() throws IOException {
        try {
            if (System.nanoTime() > 0) throw new IOException("unreadable");
        } catch (Exception e) {
            System.out.println("cleaning up");
            throw e;          // compiles: only IOException (and unchecked) can arrive here
        }
    }

    public static void main(String[] args) {
        try { read(); } catch (IOException e) { System.out.println("main got " + e.getMessage()); }
    }
}

public class Assert {
    static int half(int n) {
        assert n % 2 == 0 : "n must be even but was " + n;
        return n / 2;
    }
    public static void main(String[] args) {
        System.out.println(half(7));
    }
}

public class Cost {
    static class Quiet extends RuntimeException {
        Quiet() { super("q", null, false, false); }
    }
    static int sink;
    static void deep(int n, boolean quiet) {
        if (n == 0) throw quiet ? new Quiet() : new RuntimeException("x");
        deep(n - 1, quiet);
    }
    static long run(boolean quiet) {
        long t = System.nanoTime();
        for (int i = 0; i < 200_000; i++) {
            try { deep(50, quiet); } catch (RuntimeException e) { sink++; }
        }
        return (System.nanoTime() - t) / 1_000_000;
    }
    public static void main(String[] args) {
        run(false); run(true); // warm up
        System.out.println("with stack trace   : " + run(false) + " ms");
        System.out.println("without stack trace: " + run(true) + " ms");
    }
}

import java.util.ArrayList;
import java.util.List;

public class Errs {
    static int depth = 0;
    static void recurse() { depth++; recurse(); }

    public static void main(String[] args) {
        try { recurse(); } catch (StackOverflowError e) {
            System.out.println("SOE caught, depth > 1000: " + (depth > 1000));
        }
        try {
            List<long[]> l = new ArrayList<>();
            while (true) l.add(new long[10_000_000]);
        } catch (OutOfMemoryError e) {
            System.out.println("OOM: " + e.getMessage());
        }
    }
}
